def citation_order(lines: list[str]) -> list[str]:
    order: list[str] = []
    for line in lines:
        for group in re.findall(r"\\cite[tp]?\*?(?:\[[^\]]*\])?\{([^}]+)\}", line):
            for key in group.split(","):
                key = key.strip()
                if key and key not in order:
                    order.append(key)
    return order


